# Generated by odoo-completion. Candidates are data, never shell code.
_odoo_completion() {
    local kind value description all_nospace=1
    COMPREPLY=()
    while IFS=$'\t' read -r kind value description; do
        [ -n "$value" ] || continue
        COMPREPLY+=("$value")
        case "$kind:$value" in
            directory:*|nospace:*|*:) ;;
            *) all_nospace=0 ;;
        esac
    done < <(ODOO_COMPLETION_HELPER _complete --shell bash \
        --line "$COMP_LINE" --point "$COMP_POINT" \
        --word="${COMP_WORDS[COMP_CWORD]}" --cwd "$PWD" 2>/dev/null)
    compopt -o filenames 2>/dev/null || :
    if [ "$all_nospace" -eq 1 ] && [ "${#COMPREPLY[@]}" -gt 0 ]; then
        compopt -o nospace 2>/dev/null || :
    fi
}
complete -o filenames -F _odoo_completion odoo-bin ./odoo-bin
